head.script:
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "pop1",
        type: "window",
        width: 500,
        minimumWidth: 100,
        height: 500,
        top: 50,
        left: 50,
        popupName: "test",
        modal: true,
        useIFrame: true,
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: scroll,
        title: 'test222',
        useControl: true,
        controls: {
            minimize: true,
            maximize: true,
            close: true
        },
        foldSize: {
            width: 500
        },
        foldOnMinimized: false
    };
    $w.openPopup("windowcontainer_foldOnMinimized_WPF-1985_(WSQ-3234)_sub.xml", options);
};
scwin.checkElement = function(id) {
    if (WebSquare.wUnit.getDomById(id)) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. main샘플 실행 후 'liteWindow'버튼을 클릭한다.
    //1. After running the main sample, click the 'liteWindow' button.
    //Verify step 1. The popup window is opened.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkElement('pop1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 팝업창 우측상단의 '창사이즈최소화'버튼을 클릭한다.
    //2. Click the 'Minimize Window Size' button in the upper right corner of the popup window.
    //Verify step 2. Window size of pop-up window is minimized.(Previously, the pop-up window was hidden)
    WebSquare.wUnit.addCommand("set", "pop1_minimize.click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#pop1').css('display') == 'none'", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
